CREATE TABLE guilds (id bigserial PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, realm text NOT NULL, region text NOT NULL DEFAULT 'us', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id bigserial PRIMARY KEY, email text, display_name text, app_role text NOT NULL DEFAULT 'member' CHECK (app_role IN ('admin','officer','member')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE battle_net_identities (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, bnet_id text NOT NULL UNIQUE, battletag text NOT NULL, access_token text, refresh_token text, token_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id));
CREATE TABLE guild_memberships (id bigserial PRIMARY KEY, guild_id bigint NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, bnet_guild_rank text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,user_id));
CREATE TABLE characters (id bigserial PRIMARY KEY, guild_id bigint NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, user_id bigint REFERENCES users(id) ON DELETE SET NULL, name text NOT NULL, display_name text NOT NULL, normalized_name text NOT NULL, realm text NOT NULL, realm_slug text NOT NULL, region text NOT NULL, class_id int, class_name text, spec_id int, spec_name text, gender text, race_name text, level int, item_level numeric(6,2), guild_rank int, avatar_url text, profile_json jsonb, synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,region,realm_slug,normalized_name));
CREATE INDEX characters_guild_level_idx ON characters(guild_id,level); CREATE INDEX characters_stale_idx ON characters(guild_id,synced_at);
CREATE TABLE mythic_plus (id bigserial PRIMARY KEY, character_id bigint NOT NULL REFERENCES characters(id) ON DELETE CASCADE, season text, season_slug text NOT NULL, overall_rating numeric(8,2), best_key_level int, best_run_score numeric(8,2), dungeons jsonb, synced_at timestamptz NOT NULL, UNIQUE(character_id,season_slug));
CREATE TABLE raid_progression (id bigserial PRIMARY KEY, character_id bigint NOT NULL REFERENCES characters(id) ON DELETE CASCADE, raid_slug text NOT NULL, raid_name text, difficulty text NOT NULL, progress int DEFAULT 0, total_bosses int DEFAULT 0, summary jsonb, synced_at timestamptz NOT NULL, UNIQUE(character_id,raid_slug,difficulty));
CREATE TABLE progression_snapshots (id bigserial PRIMARY KEY, character_id bigint NOT NULL REFERENCES characters(id) ON DELETE CASCADE, captured_at timestamptz NOT NULL, item_level numeric(6,2), mythic_rating numeric(8,2), best_key_level int, raid_progress jsonb, UNIQUE(character_id,captured_at)); CREATE INDEX progression_snapshots_character_captured_idx ON progression_snapshots(character_id,captured_at);
CREATE TABLE sync_runs (id bigserial PRIMARY KEY, guild_id bigint NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, trigger text NOT NULL CHECK (trigger IN ('manual','scheduled')), status text NOT NULL CHECK (status IN ('running','success','partial','failed')), characters_total int, characters_updated int, characters_failed int, error_summary text, detail jsonb, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX sync_runs_guild_started_idx ON sync_runs(guild_id,started_at DESC);
